import random, math
from svglib import *


def profile(K, vols, lo, hi, nb):
    step = (hi - lo) / nb
    bins = [0.0] * nb
    for (o, h, l, c), v in zip(K, vols):
        b0 = max(0, int((l - lo) / step)); b1 = min(nb - 1, int((h - lo) / step))
        for b in range(b0, b1 + 1): bins[b] += v / (b1 - b0 + 1)
    return bins, step


def value_area(bins, frac=0.7):
    poc = max(range(len(bins)), key=lambda i: bins[i])
    a = b = poc; tot = bins[poc]; total = sum(bins)
    while tot < frac * total:
        up = bins[b + 1] if b + 1 < len(bins) else -1
        dn = bins[a - 1] if a - 1 >= 0 else -1
        if up >= dn: b += 1; tot += up
        else: a -= 1; tot += dn
    return poc, a, b


# ---------- fig1: candles + profile ----------
rnd = random.Random(12)
cl = []; p = 100.6
for i in range(24): p += (100.6 - p) * 0.35 + rnd.gauss(0, 0.45); cl.append(p)
for i in range(8): p += 0.45 + rnd.gauss(0, 0.2); cl.append(p)
for i in range(9): p += -0.3 + rnd.gauss(0, 0.25); cl.append(p)
K1 = ohlc(cl, seed=14, wick=0.6)
vols1 = [rnd.uniform(0.8, 1.3) * (1.4 if i < 24 else 0.8) for i in range(len(K1))]


def fig1():
    lo = min(k[2] for k in K1); hi = max(k[1] for k in K1); pad = (hi - lo) * 0.06
    lo -= pad; hi += pad
    P = Panel(20, 24, 450, 356, lo, hi, len(K1))
    bins, step = profile(K1, vols1, lo, hi, 22)
    poc, a, b = value_area(bins)
    o = head('Volume Profile: обсяг на кожному ціновому рівні, POC і зона вартості')
    mx = max(bins); bx = 470; bwmax = 150
    for i, v in enumerate(bins):
        y0 = P.Y(lo + (i + 1) * step) + 1; y1 = P.Y(lo + i * step) - 1
        col = AMBER if i == poc else VIOLET
        op = 0.95 if i == poc else (0.7 if a <= i <= b else 0.3)
        o.append(f'<rect x="{bx}" y="{y0:.1f}" width="{v/mx*bwmax:.1f}" height="{y1-y0:.1f}" rx="2" fill="{col}" fill-opacity="{op}"/>')
    yp = P.Y(lo + (poc + 0.5) * step)
    yh = P.Y(lo + (b + 1) * step); yl = P.Y(lo + a * step)
    o.append(f'<line x1="20" x2="{bx+bwmax}" y1="{yp:.1f}" y2="{yp:.1f}" stroke="{AMBER}" stroke-width="1.8" stroke-dasharray="6 5"/>')
    for y in (yh, yl):
        o.append(f'<line x1="20" x2="{bx+bwmax}" y1="{y:.1f}" y2="{y:.1f}" stroke="{MOON}" stroke-width="1.2" stroke-dasharray="3 5" stroke-opacity=".7"/>')
    o += P.candles(K1)
    o.append(text(bx + bwmax + 12, yp + 7, 'POC', AMBER, 21))
    o.append(text(bx + bwmax + 12, yh + 7, 'VAH', MOON, 20))
    o.append(text(bx + bwmax + 12, yl + 7, 'VAL', MOON, 20))
    o.append('</svg>')
    print('fig1 poc', poc, a, b, len(bins))
    return '\n'.join(o)


# ---------- fig3: two periods, two POCs ----------
def fig3():
    o = head('Профіль за годину і профіль за день мають різний POC')
    lo, hi, nb = 99, 107, 20
    Y = lambda v: 340 - (v - lo) / (hi - lo) * 280
    step = (hi - lo) / nb
    def dist(center, sd, seed, second=None):
        r = random.Random(seed); out = []
        for i in range(nb):
            pmid = lo + (i + 0.5) * step
            v = math.exp(-((pmid - center) / sd) ** 2 / 2)
            if second: v += second[2] * math.exp(-((pmid - second[0]) / second[1]) ** 2 / 2)
            out.append(v * r.uniform(0.85, 1.15))
        return out
    day = dist(101.0, 1.1, 5, (104.6, 0.6, 0.55))
    hour = dist(104.6, 0.55, 6)
    for i in range(nb):
        if lo + (i + 0.5) * step < 103.3: hour[i] = 0
    # axis labels
    for v in range(100, 107, 2):
        o.append(text(52, Y(v) + 6, f'{v}', MUTED, 18, 'end', 600))
        o.append(f'<line x1="62" x2="700" y1="{Y(v):.1f}" y2="{Y(v):.1f}" stroke="rgba(205,189,255,.08)"/>')
    for x0, name, data, col in [(80, 'за 1 годину', hour, MINT), (400, 'за день', day, VIOLET)]:
        o.append(text(x0 + 4, 46, f'Профіль {name}', col, 22))
        mx = max(data); poc = max(range(nb), key=lambda i: data[i])
        for i, v in enumerate(data):
            if v / mx < 0.06: continue
            y0 = Y(lo + (i + 1) * step) + 1; y1 = Y(lo + i * step) - 1
            c = AMBER if i == poc else col
            op = 0.95 if i == poc else 0.45
            o.append(f'<rect x="{x0}" y="{y0:.1f}" width="{v/mx*190:.1f}" height="{y1-y0:.1f}" rx="2" fill="{c}" fill-opacity="{op}"/>')
        yp = Y(lo + (poc + 0.5) * step)
        o.append(tag(x0 + 200, yp, 'POC', AMBER, 20))
        print(name, 'poc price', lo + (poc + 0.5) * step)
    o.append('</svg>')
    return '\n'.join(o)


